import 'dart:convert';

import 'package:cap_flutter/cap_flutter.dart';
import 'package:cap_flutter/src/cap_prng.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  group('fnv1a', () {
    test('matches the JS implementation', () {
      // Generated by running core/src/prng.js.
      expect(fnv1a('hello'), 1335831723);
      expect(fnv1a('tok1'), 2357093892);
    });
  });

  group('expandSeededChallenges', () {
    test('derives salt/target pairs identical to the server', () {
      // Generated by running core/src/prng.js with token "testtoken123".
      final pairs = expandSeededChallenges(
        'testtoken123',
        count: 3,
        size: 32,
        difficulty: 4,
      );
      expect(pairs, [
        ('5694189365445850278bc197a898c72b', 'af94'),
        ('fc08512633b1ac30c0c24a4bb8e6bf4e', '3a11'),
        ('949a59fa2b0bb328f0bd2e7ffb2e7c06', '2caf'),
      ]);
    });
  });

  group('CapNativeSolver.solveChallenges', () {
    test('finds the expected nonces (golden vectors)', () async {
      final solver = CapNativeSolver(apiEndpoint: 'https://example.com/x/');
      addTearDown(solver.close);
      const challenge = CapChallenge(
        token: 'testtoken123',
        count: 3,
        size: 32,
        difficulty: 4,
      );
      final nonces = await solver.solveChallenges(challenge);
      // Computed independently with Python's hashlib.
      expect(nonces, [107677, 69372, 110605]);
    });
  });

  group('CapChallenge.parse', () {
    test('parses a seeded SHA-256 challenge', () {
      final challenge = CapChallenge.parse({
        'challenge': {'c': 80, 's': 32, 'd': 4},
        'token': 'header.payload.sig',
        'expires': 123,
      });
      expect(challenge.count, 80);
      expect(challenge.size, 32);
      expect(challenge.difficulty, 4);
      expect(challenge.expires, 123);
    });

    test('rejects instrumentation challenges', () {
      expect(
        () => CapChallenge.parse({
          'challenge': {'c': 80, 's': 32, 'd': 4},
          'token': 'header.payload.sig',
          'instrumentation': 'blob',
        }),
        throwsA(isA<CapNativeUnsupportedException>()),
      );
    });

    test('rejects challenge tokens carrying instrumentation', () {
      final payload = base64Url
          .encode(utf8.encode('{"ei":"x","c":80,"s":32,"d":4}'))
          .replaceAll('=', '');
      expect(
        () => CapChallenge.parse({
          'challenge': {'c': 80, 's': 32, 'd': 4},
          'token': 'header.$payload.sig',
        }),
        throwsA(isA<CapNativeUnsupportedException>()),
      );
    });

    test('rejects non-seeded challenge formats', () {
      expect(
        () => CapChallenge.parse({
          'challenge': {'some': 'other format'},
          'token': 'header.payload.sig',
        }),
        throwsA(isA<CapNativeUnsupportedException>()),
      );
    });

    test('surfaces server errors as CapError', () {
      expect(
        () => CapChallenge.parse({'error': 'Invalid site key or secret'}),
        throwsA(
          isA<CapError>().having(
            (e) => e.message,
            'message',
            'Invalid site key or secret',
          ),
        ),
      );
    });
  });
}
